const crypto = require('crypto');

const webhookItem = $('Webhook: Message').first();
const headers = webhookItem.json.headers || {};
const body = webhookItem.json.body || {};

const secret = ($env.WEBHOOK_SECRET || '').trim();
if (!secret) {
  throw new Error('WEBHOOK_SECRET not set');
}

const signature = (headers['x-signature'] || headers['X-Signature'] || '').toLowerCase();
function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map((item) => stableStringify(item)).join(',') + ']';
  return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
}
const payload = stableStringify(body);
const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex');

if (!signature || signature.length !== 64) {
  throw new Error('Missing or invalid X-Signature header');
}

const sigBuf = Buffer.from(signature, 'hex');
const expBuf = Buffer.from(expected, 'hex');
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Invalid webhook signature');
}

return [{ json: body }];

