// Word Replacement Engine — runs on single messages
const rules = $json.replacement_rules || [];

function shiftEntities(entities, replaceStart, oldLen, newLen) {
  const replaceEnd = replaceStart + oldLen;
  const delta = newLen - oldLen;
  const result = [];
  for (const ent of entities) {
    const eStart = ent.offset;
    const eEnd = eStart + ent.length;
    if (eEnd <= replaceStart) {
      result.push(ent);
    } else if (eStart >= replaceEnd) {
      result.push({ ...ent, offset: eStart + delta });
    } else if (eStart <= replaceStart && eEnd >= replaceEnd) {
      const newLen2 = ent.length + delta;
      if (newLen2 > 0) result.push({ ...ent, length: newLen2 });
    }
    // overlapping entity dropped
  }
  return result;
}

function applyReplacements(text, rules, entities) {
  if (!text || typeof text !== 'string') return { text, entities };
  let result = text;
  let liveEntities = entities ? [...entities] : [];
  let entitiesValid = true;
  for (const rule of rules) {
    if (!rule || !rule.pattern) continue;
    const replacement = rule.replacement || '';
    if (rule.is_regex) {
      try {
        const newResult = result.replace(new RegExp(rule.pattern, 'gm'), replacement);
        if (newResult !== result) { result = newResult; entitiesValid = false; liveEntities = []; }
      } catch (e) {}
    } else {
      const oldLen = rule.pattern.length;
      const newLen = replacement.length;
      let searchStart = 0;
      while (true) {
        const idx = result.indexOf(rule.pattern, searchStart);
        if (idx === -1) break;
        result = result.slice(0, idx) + replacement + result.slice(idx + oldLen);
        if (entitiesValid && liveEntities.length) {
          liveEntities = shiftEntities(liveEntities, idx, oldLen, newLen);
        }
        searchStart = idx + newLen;
      }
    }
  }
  const finalEntities = entitiesValid && liveEntities.length ? liveEntities : null;
  return { text: result, entities: finalEntities };
}

const data = {...$json};
if (data.text) {
  const r = applyReplacements(data.text, rules, data.entities || []);
  data.processed_text = r.text;
  data.text_changed = data.processed_text !== data.text;
  if (r.entities !== null) data.processed_entities = r.entities;
  else if (data.text_changed) data.processed_entities = [];
}
if (data.caption) {
  const r = applyReplacements(data.caption, rules, data.caption_entities || []);
  data.processed_caption = r.text;
  data.caption_changed = data.processed_caption !== data.caption;
  if (r.entities !== null) data.processed_caption_entities = r.entities;
  else if (data.caption_changed) data.processed_caption_entities = [];
}
return [{json: data}];

